"""Ephemeral upstream test fixtures, generated by OpenSSH, never account keys.

The public repository stores only this generator and public verification vectors.
Run through run.py so private material is restricted to a cleaned temporary tree.
PPK serialization is independent of the Rust decoder under test. PuTTY's format:
https://www.chiark.greenend.org.uk/~sgtatham/putty/0.85/htmldoc/AppendixC.html
SPDX-License-Identifier: MIT OR Apache-2.0
"""
import base64
import hashlib
import hmac
import os
import pathlib
import shutil
import struct
import subprocess

from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.kdf.argon2 import Argon2id
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import dsa


def string(value):
    return struct.pack('>I', len(value)) + value


class Reader:
    def __init__(self, data):
        self.data, self.offset = data, 0

    def take(self, size):
        result = self.data[self.offset:self.offset + size]
        if len(result) != size:
            raise ValueError('truncated fixture structure')
        self.offset += size
        return result

    def number(self):
        return struct.unpack('>I', self.take(4))[0]

    def string(self):
        return self.take(self.number())


def unpack(path):
    data = base64.b64decode(b''.join(path.read_bytes().splitlines()[1:-1]))
    reader = Reader(data)
    if reader.take(15) != b'openssh-key-v1\0':
        raise ValueError('not OpenSSH v1')
    cipher, kdf, options = (reader.string() for _ in range(3))
    if reader.number() != 1:
        raise ValueError('expected exactly one test key')
    public, private = reader.string(), reader.string()
    return cipher, kdf, options, public, private


def fields(path):
    cipher, _, _, public, private = unpack(path)
    if cipher != b'none':
        raise ValueError('oracle requires plaintext generated by external OpenSSH')
    reader = Reader(private)
    check = reader.take(8)
    if check[:4] != check[4:]:
        raise ValueError('bad checkints')
    algorithm = reader.string()
    names = {
        b'ssh-dss': ('p', 'q', 'g', 'y', 'x'),
        b'ssh-rsa': ('n', 'e', 'd', 'iqmp', 'p', 'q'),
        b'ssh-ed25519': ('public', 'secret'),
    }.get(algorithm, ('curve', 'public', 'scalar'))
    values = {name: reader.string() for name in names}
    comment = reader.string()
    return algorithm, public, values, comment, check


def write(path, data):
    path.write_bytes(data.encode() if isinstance(data, str) else data)
    path.chmod(0o600)


def pem(public, private, columns=70):
    data = b'openssh-key-v1\0' + string(b'none') * 2 + string(b'')
    data += struct.pack('>I', 1) + string(public) + string(private)
    encoded = base64.b64encode(data)
    # These markers describe a file format, not a stored private-key fixture.
    marker = b'OPENSSH PRIVATE KEY'
    return b'-----BEGIN ' + marker + b'-----\n' + b'\n'.join(
        encoded[i:i + columns] for i in range(0, len(encoded), columns)
    ) + b'\n-----END ' + marker + b'-----\n'


def rewrite(source, destination, comment, block=8, omit_padding=False):
    algorithm, public, values, _, check = fields(source)
    private = check + string(algorithm)
    private += b''.join(string(value) for value in values.values()) + string(comment)
    if omit_padding:
        if len(private) % block:
            return False
    else:
        amount = block - len(private) % block
        private += bytes(range(1, amount + 1))
    write(destination, pem(public, private))
    return True


def command(args, env):
    result = subprocess.run(args, env=env, stdin=subprocess.DEVNULL,
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if result.returncode:
        # External stderr may contain material; never copy it to persistent logs.
        raise RuntimeError('external fixture tool failed: ' + args[0] +
                           ' (exit ' + str(result.returncode) + ')')
    return result.stdout


def new_key(path, kind, bits, env):
    for item in (path, pathlib.Path(str(path) + '.pub')):
        item.unlink(missing_ok=True)
    if kind == 'dsa':
        # OpenSSH 10 removed DSA. Independent OpenSSL-backed cryptography keeps
        # the legacy decoder test effective; it is never used for authentication.
        key = dsa.generate_private_key(key_size=bits)
        write(path, key.private_bytes(serialization.Encoding.PEM,
                                     serialization.PrivateFormat.OpenSSH,
                                     serialization.NoEncryption()))
        rewrite(path, path, b'user@example.com')
        write(pathlib.Path(str(path) + '.pub'), key.public_key().public_bytes(
            serialization.Encoding.OpenSSH, serialization.PublicFormat.OpenSSH)
            + b' user@example.com\n')
        return
    args = ['ssh-keygen', '-q', '-t', kind, '-N', '', '-C', 'user@example.com', '-f', str(path)]
    if bits:
        args += ['-b', str(bits)]
    command(args, env)
    path.chmod(0o600)


def ppk(source, destination, version, encrypted):
    algorithm, public, values, comment, _ = fields(source)
    names = {b'ssh-dss': ('x',), b'ssh-rsa': ('d', 'p', 'q', 'iqmp'),
             b'ssh-ed25519': ('secret',)}.get(algorithm, ('scalar',))
    private = b''.join(string(values[name][:32] if algorithm == b'ssh-ed25519'
                              else values[name]) for name in names)
    password = b'123' if encrypted else b''  # Synthetic test password only.
    encryption = b'aes256-cbc' if encrypted else b'none'
    headers = []
    if encrypted:
        private += os.urandom((-len(private)) % 16)
    if version == 3 and encrypted:
        salt = os.urandom(16)
        # Retain the upstream cases' nonsecret work parameters, rather than
        # reducing their coverage merely to make generated tests faster.
        passes = 21 if algorithm == b'ssh-dss' else 34
        derived = Argon2id(salt=salt, length=80, iterations=passes,
                          lanes=1, memory_cost=8192).derive(password)
        key, iv, mac_key = derived[:32], derived[32:48], derived[48:]
        headers = ['Key-Derivation: Argon2id', 'Argon2-Memory: 8192',
                   'Argon2-Passes: ' + str(passes), 'Argon2-Parallelism: 1',
                   'Argon2-Salt: ' + salt.hex()]
    elif version == 2:
        key = b''.join(hashlib.sha1(struct.pack('>I', i) + password).digest()
                       for i in range(2))[:32]
        iv = bytes(16)
        mac_key = hashlib.sha1(b'putty-private-key-file-mac-key' + password).digest()
    else:
        mac_key = b''
    mac_data = b''.join(string(x) for x in (algorithm, encryption, comment, public, private))
    mac = hmac.new(mac_key, mac_data, 'sha1' if version == 2 else 'sha256').hexdigest()
    if encrypted:
        encryptor = Cipher(algorithms.AES(key), modes.CBC(iv)).encryptor()
        private = encryptor.update(private) + encryptor.finalize()

    def lines(data):
        value = base64.b64encode(data).decode()
        return [value[i:i + 64] for i in range(0, len(value), 64)]

    pub_lines, private_lines = lines(public), lines(private)
    result = [f'PuTTY-User-Key-File-{version}: {algorithm.decode()}',
              'Encryption: ' + encryption.decode(), 'Comment: ' + comment.decode(),
              'Public-Lines: ' + str(len(pub_lines)), *pub_lines, *headers,
              'Private-Lines: ' + str(len(private_lines)), *private_lines,
              'Private-MAC: ' + mac]
    write(destination, '\n'.join(result) + '\n')


def dsa_messages(values):
    """Independent RFC6979/SHA1 oracle; retain full and 19-byte-r cases.

    Messages are nonsecret counters. The key is fresh OpenSSL-generated material;
    no historical private scalar or signature fixture is reconstructed.
    """
    p, q, g, x = (int.from_bytes(values[field], 'big') for field in ('p', 'q', 'g', 'x'))
    found = {}
    for number in range(65536):
        message = b'ephemeral-dsa-boundary-' + struct.pack('>I', number)
        digest = hashlib.sha1(message).digest()
        reduced = (int.from_bytes(digest, 'big') % q).to_bytes(20, 'big')
        seed = x.to_bytes(20, 'big') + reduced
        k, v = bytes(20), b'\x01' * 20
        for separator in (b'\0', b'\x01'):
            k = hmac.new(k, v + separator + seed, 'sha1').digest()
            v = hmac.new(k, v, 'sha1').digest()
        while True:
            v = hmac.new(k, v, 'sha1').digest()
            nonce = int.from_bytes(v, 'big')
            if 0 < nonce < q:
                r = pow(g, nonce, p) % q
                s = (pow(nonce, -1, q) * (int.from_bytes(digest, 'big') + x * r)) % q
                if r and s:
                    break
            k = hmac.new(k, v + b'\0', 'sha1').digest()
            v = hmac.new(k, v, 'sha1').digest()
        lengths = ((r.bit_length() + 7) // 8, (s.bit_length() + 7) // 8)
        label = {(20, 20): 'full', (19, 20): 'short'}.get(lengths)
        if label and label not in found:
            found[label] = message
        if len(found) == 2:
            return {'dsa.' + key + '_message': value for key, value in found.items()}
    raise RuntimeError('bounded independent DSA short-component search exhausted')


def generate(root, project, env):
    """root must be a private temporary directory owned by the caller."""
    root.chmod(0o700)
    examples = root / 'tests/examples'
    examples.mkdir(parents=True, mode=0o700)
    extra = root / 'extra'
    extra.mkdir(mode=0o700)
    oracle = {}
    specs = [('id_dsa_1024', 'dsa', 1024), ('id_ed25519', 'ed25519', None),
             *[(f'id_ecdsa_p{n}', 'ecdsa', n) for n in (256, 384, 521)],
             *[(f'id_rsa_{n}', 'rsa', n) for n in (3072, 4096)]]
    for name, kind, bits in specs:
        new_key(examples / name, kind, bits, env)
        alg, public, values, _, _ = fields(examples / name)
        for field, value in values.items():
            if field == 'secret':
                value = value[:32]
                field = 'private'
            if field == 'scalar':
                value = int.from_bytes(value, 'big').to_bytes((bits + 7) // 8, 'big')
            oracle[name + '.' + field] = value
        oracle[name + '.fingerprint'] = hashlib.sha256(public).digest()
        if name == 'id_dsa_1024':
            oracle.update(dsa_messages(values))

    # Public-only golden inputs stay unchanged for independent known-vector tests.
    for source in (project / 'vendor/ssh-key-0.7.0-rc.11/tests/examples').iterdir():
        if source.name.endswith('.pub') and not (examples / source.name).exists():
            shutil.copyfile(source, examples / source.name)

    ciphers = ['aes128-cbc', 'aes192-cbc', 'aes256-cbc', 'aes128-ctr',
               'aes192-ctr', 'aes256-ctr', 'aes128-gcm', 'aes256-gcm',
               'chacha20-poly1305', '3des-cbc']
    for cipher in ciphers:
        path = examples / ('id_ed25519.' + cipher + '.enc')
        shutil.copyfile(examples / 'id_ed25519', path)
        path.chmod(0o600)
        wire_cipher = cipher + '@openssh.com' if cipher.endswith('gcm') or cipher == 'chacha20-poly1305' else cipher
        command(['ssh-keygen', '-q', '-p', '-P', '', '-N', 'hunter42',
                 '-a', '16', '-Z', wire_cipher, '-f', str(path)], env)
        options = Reader(unpack(path)[2])
        oracle[cipher + '.salt'] = options.string()
        if options.number() != 16:
            raise ValueError('unexpected external bcrypt rounds')

    for name in ('id_dsa_1024', 'id_ecdsa_p256', 'id_ed25519', 'id_rsa_3072'):
        for encrypted in (False, True):
            suffix = '_enc' if encrypted else ''
            ppk(examples / name, examples / (name + suffix + '.ppk'), 3, encrypted)
            if name == 'id_rsa_3072':
                ppk(examples / name, examples / (name + suffix + '.ppk2'), 2, encrypted)

    _, _, _, public, private = unpack(examples / 'id_ed25519')
    write(examples / 'id_ed25519.64cols', pem(public, private, 64))
    rewrite(examples / 'id_ed25519', examples / 'puttygen_overpadded',
            b'eddsa-key-20241227a1234567890', block=16)
    rewrite(examples / 'id_ed25519', examples / 'non_utf8_comment',
            b'star_@\xB2\xDC\xC8\xF1\xC8\xF1\xC8\xF1\xB5\xC4\xB5\xE7\xC4\xD4')
    # Generate rather than encode/reconstruct upstream's historic private values.
    for name, bits, predicate in [('padless_wonder', 256, lambda v: len(v) % 8 == 0),
                                  ('paramiko_ecdsa', 521, lambda v: len(v.lstrip(b'\0')) == 65)]:
        source = extra / ('padless-source' if name == 'padless_wonder' else name)
        for _ in range(128):
            new_key(source, 'ecdsa', bits, env)
            values = fields(source)[2]
            if name == 'padless_wonder':
                if rewrite(source, examples / name, b'', omit_padding=True):
                    break
            elif predicate(values['scalar']):
                oracle[name + '.scalar'] = int.from_bytes(values['scalar'], 'big').to_bytes(66, 'big')
                break
        else:
            raise RuntimeError('could not generate bounded edge-case fixture')

    opaque_public, opaque_private = os.urandom(32), os.urandom(32)
    alg = b'name@example.com'
    public = string(alg) + string(opaque_public)
    check = os.urandom(4) * 2
    private = check + string(alg) + string(opaque_public) + string(opaque_private)
    private += string(b'comment@example.com')
    private += bytes(range(1, 9 - len(private) % 8))
    write(examples / 'id_opaque', pem(public, private))
    oracle.update({'id_opaque.public': opaque_public, 'id_opaque.private': opaque_private})

    for name, kind, bits in [('ca_ed25519', 'ed25519', None), ('ca_ecdsa', 'ecdsa', 256),
                             ('subject_ed25519', 'ed25519', None), ('subject_ecdsa', 'ecdsa', 256)]:
        new_key(extra / name, kind, bits, env)
    message = extra / 'message'
    write(message, b'testing')
    command(['ssh-keygen', '-Y', 'sign', '-f', str(examples / 'id_ed25519'),
             '-n', 'example', str(message)], env)
    write(root / 'oracle.tsv', ''.join(name + '\t' + value.hex() + '\n'
                                      for name, value in sorted(oracle.items())))
    return {'generated_private_resources': 32, 'ciphers': len(ciphers),
            'puttygen_interoperability': 'not executed; independent PPK writer'}
